vector<vector<int>> build2DPrefix(vector<vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();

    vector<vector<int>> P(m + 1, vector<int>(n + 1, 0)); // 1-indexed

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            P[i][j] = grid[i - 1][j - 1]
                    + P[i - 1][j]
                    + P[i][j - 1]
                    - P[i - 1][j - 1];
        }
    }

    return P;
}

// Query sum of rectangle (r1,c1) to (r2,c2) - 1-indexed
int query2D(vector<vector<int>>& P, int r1, int c1, int r2, int c2) {
    return P[r2][c2]
         - P[r1 - 1][c2]
         - P[r2][c1 - 1]
         + P[r1 - 1][c1 - 1];
}

