public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> seen;
        seen[0] = 1; // prefix sum 0 seen once

        int count = 0;
        int prefix = 0;

        for (int num : nums) {
            prefix += num;

            // subarrays ending here with sum k
            count += seen[prefix - k];

            seen[prefix]++;
        }

        return count;
    }
};

